import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
/*eslint-disable*/
import { API, graphqlOperation } from "aws-amplify";
import { Get_holiday_list_portal_v1 } from "@/graphql/queries.js";
import { get_location_details } from "@/mixins/GetLocations.js";
import { create_custom_holidays } from "@/graphql/mutations.js";
export default {
  mixins: [get_location_details],
  data() {
    return {
      loaction: "",
      searchloc: "",
      loactionitems: [],
      loadingcustom: false,
      holidayName: "",
      menu: false,
      date: "",
      fixed: true,
      holidayHeaders: [{
        title: "Name",
        key: "holiday_name",
        sortable: false
      }, {
        title: "Date",
        key: "holiday_date",
        sortable: false
      }, {
        title: "Action",
        key: "actions",
        sortable: false
      }],
      tableLoading: false,
      holidaylist: [],
      tableData: [],
      checkholiday: false,
      datePicker: false,
      tempDate: null,
      date1: null
    };
  },
  props: {
    holidayadd: Boolean,
    rowInfo: Object
  },
  watch: {
    holidayadd: {
      async handler() {
        this.checkholiday = this.$store.getters.GetOrgDetails.organization.default_holiday_list == undefined ? true : this.$store.getters.GetOrgDetails.organization.default_holiday_list;
        await this.get_location_details();
        await this.fetch_details();
        await this.get_holiday_list();
      },
      immediate: true
    },
    loaction: {
      handler(newVal) {
        if (newVal && newVal.location_id) {
          this.filtertable();
        } else {
          // Reset table data when location is cleared
          this.tableData = [];
          if (this.holidaylist && Array.isArray(this.holidaylist)) {
            this.tableData = [...this.holidaylist];
          }
        }
      },
      immediate: false
    }
  },
  methods: {
    saveDate() {
      this.date1 = this.tempDate;
      this.date = this.tempDate ? this.formatDate(this.tempDate) : "";
      this.datePicker = false;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    },
    filtertable() {
      this.tableData = [];
      if (this.holidaylist && Array.isArray(this.holidaylist)) {
        this.tableData = [...this.holidaylist];

        // Only filter if loaction is selected
        if (this.loaction && this.loaction.location_id) {
          this.tableData = this.tableData.filter(holiday => holiday.holiday_location === this.loaction.location_id);
        }
      }
    },
    close_dialog() {
      // Reset form validation and form
      if (this.$refs.form2) {
        this.$refs.form2.resetValidation();
        this.$refs.form2.reset();
      }

      // Reset all data values
      this.loaction = null;
      this.searchloc = "";
      this.holidayName = "";
      this.date = "";
      this.tableData = [];
      this.tempDate = null;
      this.date1 = null;
      this.$emit("clicked", 0);
    },
    add_action() {
      if (this.holidayName != "" && this.holidayName != null && this.date != "" && this.date != null) {
        const exists = this.tableData.some(item => item.holiday_date === this.date);
        if (!exists) {
          this.tableData.push({
            holiday_name: this.holidayName,
            holiday_date: this.date
          });
          this.date = "";
          this.holidayName = "";
        } else {
          this.$emit("errorMsg", "Holiday date already exists");
        }
      } else {
        this.$emit("errorMsg", "Enter Holiday Name and Date");
      }
    },
    fetch_details() {
      if (this.locationList && Array.isArray(this.locationList)) {
        this.locationList.forEach(element => {
          this.loactionitems.push({
            title: element.location_name,
            location_id: element.location_id
          });
        });
      }
    },
    async validate_default_data() {
      const {
        valid
      } = await this.$refs.form2.validate();
      if (valid) {
        this.add_holiday_list();
      }
    },
    async add_holiday_list() {
      this.loadingcustom = true;
      try {
        let result = await API.graphql(graphqlOperation(create_custom_holidays, {
          input: {
            holiday_details: JSON.stringify(this.tableData),
            holiday_location: this.loaction?.location_id || "",
            holiday_location_name: this.loaction?.location_name || ""
          }
        }));
        this.loadingcustom = false;
        var response = JSON.parse(result.data.create_custom_holidays);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form2.resetValidation();
          this.$refs.form2.reset();
          this.loadingcustom = false;
        } else {
          this.loadingcustom = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loadingcustom = false;
      }
    },
    deleteItem(item) {
      const index = this.tableData.indexOf(item);
      if (index > -1) {
        this.tableData.splice(index, 1); // Remove item from the array
      }
    },
    async get_holiday_list() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(Get_holiday_list_portal_v1, {
          input: {
            organization_id: data.organization.organization_id,
            holiday_year: new Date().getFullYear()
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.Get_holiday_list_portal_v1);
        if (response.Status == "SUCCESS") {
          var holiaydata = response.Data.filter(holiday => holiday.holiday_location === "" || holiday.holiday_location === undefined);
          this.holidaylist = response.Data;
          holiaydata.forEach(element => {
            this.tableData.push({
              holiday_date: element.holiday_date,
              holiday_name: element.holiday_name
            });
          });
        } else {
          this.tableData = [];
        }
      } catch (error) {
        // console.log(error);
        this.tableLoading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
